/*
 * extmem.c
 * Zhaonian Zou
 * Harbin Institute of Technology
 * Jun 22, 2011
 */

#include <stdlib.h>
#include <stdio.h>
#include <string.h> // added for memset
#include "extmem.h"

Buffer *initBuffer(size_t bufSize, size_t blkSize, Buffer *buf)
{
	if (buf == NULL || blkSize == 0)
		return NULL;

	/* Every block occupies blkSize + 1 bytes of the buffer: one leading byte
	 * flags whether the slot is available, the remaining blkSize bytes hold
	 * the block payload that is handed out to the caller. */
	buf->numIO = 0;
	buf->bufSize = bufSize;
	buf->blkSize = blkSize;
	buf->numAllBlk = bufSize / (blkSize + 1);
	buf->numFreeBlk = buf->numAllBlk;

	if ((buf->data = (unsigned char *)malloc(bufSize)) == NULL)
	{
		perror("Buffer Initialization Failed!\n");
		return NULL;
	}

	memset(buf->data, 0, bufSize); /* every slot starts out BLOCK_AVAILABLE */

	return buf;
}

void freeBuffer(Buffer *buf)
{
	free(buf->data);
}

unsigned char *getNewBlockInBuffer(Buffer *buf)
{
	unsigned char *blkPtr;
	size_t i;

	if (buf == NULL || buf->numFreeBlk == 0)
	{
		perror("Buffer Overflows!\n");
		return NULL;
	}

	/* Scan the slots for the first available one, mark it used and return
	 * the payload address (the byte right after the availability flag). */
	for (i = 0; i < buf->numAllBlk; i++)
	{
		blkPtr = buf->data + i * (buf->blkSize + 1);
		if (*blkPtr == BLOCK_AVAILABLE)
		{
			*blkPtr = BLOCK_UNAVAILABLE;
			buf->numFreeBlk--;
			return blkPtr + 1;
		}
	}

	perror("Buffer Overflows!\n");
	return NULL;
}

void freeBlockInBuffer(unsigned char *blk, Buffer *buf)
{
	if (blk == NULL || buf == NULL)
		return;

	/* The availability flag sits one byte in front of the payload. */
	unsigned char *blkPtr = blk - 1;

	if (*blkPtr == BLOCK_AVAILABLE) /* already free: do not double count */
		return;

	*blkPtr = BLOCK_AVAILABLE;
	memset(blk, 0, buf->blkSize);
	buf->numFreeBlk++;
}

int dropBlockOnDisk(unsigned int addr)
{
	char filename[40];

	sprintf(filename, "%d.blk", addr);

	if (remove(filename) == -1)
	{
		perror("Dropping Block Fails!\n");
		return -1;
	}

	return 0;
}

